static void allocate(int cap){int dp[MAX_BAGS+1][201]={{0}};int unit[MAX_BAGS];for(int i=0;i<bagN;i++)unit[i]=bags[i]*10;for(int i=1;i<=bagN;i++)for(int c=0;c<=cap*10;c++){dp[i][c]=dp[i-1][c];if(unit[i-1]<=c&&dp[i-1][c-unit[i-1]]+unit[i-1]>dp[i][c])dp[i][c]=dp[i-1][c-unit[i-1]]+unit[i-1];}memset(chosen,0,sizeof(chosen));int c=cap*10;for(int i=bagN;i>0;i--)if(dp[i][c]!=dp[i-1][c]){chosen[i-1]=1;c-=unit[i-1];}bagCap=cap;bagTaken=dp[bagN][cap*10]/10;}
